import{_ as i,o,c as a,a2 as t}from"./chunks/framework.BN2sqjC1.js";const m=JSON.parse('{"title":"Sincronizzazione e cloud","description":"","frontmatter":{},"headers":[],"relativePath":"user-guide/sync-cloud.md","filePath":"user-guide/sync-cloud.md"}'),n={name:"user-guide/sync-cloud.md"};function l(r,e,s,c,d,u){return o(),a("div",null,[...e[0]||(e[0]=[t('<h1 id="sincronizzazione-e-cloud" tabindex="-1">Sincronizzazione e cloud <a class="header-anchor" href="#sincronizzazione-e-cloud" aria-label="Permalink to &quot;Sincronizzazione e cloud&quot;">​</a></h1><p>La sincronizzazione è <strong>facoltativa</strong>. Serve un server Clarae notanda (fornito dalla vostra organizzazione) e un account.</p><h2 id="collegarsi-al-server" tabindex="-1">Collegarsi al server <a class="header-anchor" href="#collegarsi-al-server" aria-label="Permalink to &quot;Collegarsi al server&quot;">​</a></h2><ol><li><em>Impostazioni → Cloud</em>: inserite l&#39;<strong>URL del server</strong> (il resto della configurazione si scarica da lì) e scegliete <em>Accedi</em>.</li><li>Il login si completa nel <strong>browser di sistema</strong> (non nell&#39;app): se il collegamento locale non è possibile, l&#39;app ripiega sullo schema <code>clarae://</code> (se il realm del server è stato creato per la 1.x e non ha il redirect nuovo, ricade da sola su quello precedente). Il token di rinnovo è custodito nel <strong>portachiavi</strong> del sistema.</li><li>Sotto <em>Cloud</em> vedete il profilo, lo spazio usato e i <strong>dispositivi</strong> collegati (si possono revocare). Nell&#39;elenco dello spazio, ogni vault mostra la <strong>percentuale rispetto al vostro limite</strong> (non rispetto alla somma dei vault); con spazio illimitato mostra «—». Un suggerimento sulla cella dice il limite.</li></ol><h3 id="uscire" tabindex="-1">Uscire <a class="header-anchor" href="#uscire" aria-label="Permalink to &quot;Uscire&quot;">​</a></h3><p><em>Esci</em> (nel menu dell&#39;account) ferma la sincronizzazione, <strong>revoca questo dispositivo</strong> sul cloud, chiude la vostra sessione sul servizio di accesso e cancella la sessione locale; i vault e le modifiche non ancora inviate restano sul computer. Se manca la rete l&#39;uscita avviene comunque: il dispositivo resta registrato e al prossimo accesso viene ripreso. <strong>Il successivo <em>Accedi</em> chiede di nuovo la password</strong>, anche se il browser di sistema ricorda ancora l&#39;accesso.</p><p>Un computer è identificato dal <strong>nome</strong> con cui il sistema lo conosce (e dalla piattaforma): dopo <em>Esci</em> e un nuovo accesso compare <strong>la stessa riga</strong> nell&#39;elenco dei dispositivi, non una nuova. Due computer con lo stesso nome diventano un solo dispositivo: rinominatene uno. Un dispositivo che avete revocato dalla Web UI e che poi si ricollega <strong>con lo stesso nome</strong> viene riattivato.</p><h2 id="collegare-un-vault" tabindex="-1">Collegare un vault <a class="header-anchor" href="#collegare-un-vault" aria-label="Permalink to &quot;Collegare un vault&quot;">​</a></h2><p><em>Collega il vault al cloud</em> (palette comandi) avvia una procedura guidata. Dovete scegliere il <strong>tipo di vault</strong>, e la scelta è <strong>definitiva</strong>:</p><ul><li><strong>Condiviso</strong> (non cifrato end-to-end): condivisibile con altri utenti e gruppi;</li><li><strong>Privato</strong> (cifrato end-to-end): solo vostro, non condivisibile.</li></ul><p>Leggete <a href="./vault-privati-condivisi.html">Vault privati e condivisi</a> prima di scegliere. Si può anche collegare un vault già presente sul server (altro dispositivo): i file vengono scaricati nella cartella scelta.</p><h2 id="gestire-i-vault-nel-cloud" tabindex="-1">Gestire i vault nel cloud <a class="header-anchor" href="#gestire-i-vault-nel-cloud" aria-label="Permalink to &quot;Gestire i vault nel cloud&quot;">​</a></h2><p><em>Impostazioni → Cloud</em> (sul desktop e nel workbench del browser) e la pagina <em>I miei vault</em> della Web UI elencano i vostri vault nel cloud con dimensione, numero di file e data di creazione. Da lì:</p><ul><li><strong>Creare:</strong> sul desktop <em>Nuovo vault</em> apre la procedura <em>Collega il vault al cloud</em> per il vault aperto (se non è già collegato). Nella Web UI <em>Nuovo vault</em> chiede nome e tipo: un vault <strong>condiviso</strong> si crea subito; per un vault <strong>privato</strong> si apre il workbench del browser, che chiede la passphrase (due volte, almeno 12 caratteri) e mostra la chiave di recupero una sola volta, poi apre il vault appena creato. Le chiavi di un vault privato si creano sempre sul vostro dispositivo, mai sul server. Annullando si torna alla Web UI e non resta nulla.</li><li><strong>Rinominare:</strong> il nuovo nome vale per tutti i dispositivi e per la Web UI. Le cartelle sul computer <strong>non</strong> cambiano nome: cambia solo il nome mostrato in <em>Impostazioni → Sincronizzazione</em>.</li><li><strong>Eliminare:</strong> l&#39;eliminazione è <strong>logica</strong>. Il server conserva il vault per il periodo di conservazione stabilito dall&#39;amministratore (30 giorni se non diversamente configurato); in quel periodo il vault compare in <em>Vault eliminati</em> e si può <strong>ripristinare</strong>, poi viene rimosso definitivamente. Sul dispositivo da cui lo eliminate, la copia locale <strong>resta con tutti i suoi file</strong> e viene <strong>scollegata</strong> dal cloud; per un vault privato il dispositivo dimentica anche la chiave. Gli altri dispositivi collegati smettono di sincronizzarlo (la loro copia locale resta dov&#39;è: scollegatela da <em>Impostazioni → Sincronizzazione</em>) e chi lo riceveva in condivisione perde l&#39;accesso. Nel workbench del browser il vault aperto nella pagina non si elimina da lì: tornate alla Web UI.</li><li><strong>Ripristinare:</strong> il vault torna nell&#39;elenco con il suo contenuto e la sua cronologia. Non si ricollega da solo: sul dispositivo collegatelo di nuovo come <em>vault già presente sul server</em> (per un vault privato servono passphrase o chiave di recupero). Se nel frattempo avete creato un altro vault con lo stesso nome, rinominate prima quello.</li></ul><h2 id="come-funziona" tabindex="-1">Come funziona <a class="header-anchor" href="#come-funziona" aria-label="Permalink to &quot;Come funziona&quot;">​</a></h2><p>Il client elenca le modifiche del server, scarica quelle nuove, poi invia le proprie. L&#39;indicatore in fondo alla barra laterale destra (nell&#39;intestazione se la barra è chiusa) mostra: sincronizzato, in corso, offline, errore, conflitti, account sospeso, vault bloccato. <em>Sincronizza ora</em> (<code>Mod+Maiusc+S</code>) forza un ciclo. Le notifiche dal server rendono la sincronizzazione quasi immediata; in assenza il client controlla periodicamente (intervallo configurabile in <em>Impostazioni → Sincronizzazione</em>, salvo diversa indicazione dell&#39;amministratore).</p><p>Si sincronizzano le note, gli allegati e i file di tipo <code>.canvas</code>, <code>.base</code>, <code>.excalidraw</code>, più alcune impostazioni (segnalibri, scorciatoie…). <strong>Non</strong> si sincronizzano l&#39;indice di ricerca, i workspace e le impostazioni specifiche del dispositivo.</p><h3 id="file-non-inviati" tabindex="-1">File non inviati <a class="header-anchor" href="#file-non-inviati" aria-label="Permalink to &quot;File non inviati&quot;">​</a></h3><p><em>Impostazioni → Sincronizzazione</em> ha un blocco <strong>File non inviati</strong>: elenca i file di questo dispositivo che non arrivano al cloud, raggruppati per motivo, con il numero di file di ogni gruppo e, accanto al percorso, il codice o il dettaglio dell&#39;errore. Se non c&#39;è nulla da segnalare compare «Tutti i file sono stati inviati.». L&#39;elenco si aggiorna da solo a ogni ciclo di sincronizzazione.</p><table tabindex="0"><thead><tr><th>Motivo mostrato</th><th>Che cosa significa e che cosa fare</th></tr></thead><tbody><tr><td>Troppo grandi</td><td>Il file supera il limite di dimensione per file stabilito dall&#39;amministratore. Riducetelo o tenetelo fuori dal vault, poi <em>Riprova</em>.</td></tr><tr><td>Cifratura non riuscita</td><td>Il percorso o il contenuto non si è potuto cifrare (vault privato). <em>Riprova</em>; se si ripete, controllate il log.</td></tr><tr><td>Spostamento che svuoterebbe una cartella condivisa</td><td>Lo spostamento lascerebbe vuota una cartella condivisa con voi. Rimettete il file al suo posto, oppure <em>Riprova</em> dopo aver cambiato lo spostamento.</td></tr><tr><td>Rifiutati dal server</td><td>Il server ha rifiutato il file; il codice è accanto al percorso. Dopo aver rimosso la causa, <em>Riprova</em>.</td></tr><tr><td>In errore, si riprova</td><td>L&#39;invio è fallito e l&#39;app ritenta da sola: di solito non serve fare nulla. Se il file passa a un altro gruppo, agite secondo quel motivo.</td></tr><tr><td>Troppe modifiche concorrenti: risolvi i conflitti</td><td>Altri dispositivi continuano a modificare il file. Usate <em>Risolvi conflitti di sincronizzazione</em> (vedi <a href="#conflitti">Conflitti</a>).</td></tr><tr><td>In attesa di unire una modifica del server</td><td>Il file sarà inviato dopo l&#39;unione di una modifica arrivata dal server: lo risolve il ciclo successivo.</td></tr><tr><td>Nome non valido: rinomina il file</td><td>Il nome non è ammesso dalle regole del vault (per esempio caratteri o formato non rappresentabili): rinominate il file.</td></tr><tr><td>Collegamenti simbolici (mai seguiti)</td><td>I collegamenti simbolici non si sincronizzano mai. Se serve il contenuto, copiatelo nel vault come file.</td></tr></tbody></table><p>Gli ultimi due motivi dell&#39;elenco non sono errori: sotto <strong>Cartelle escluse</strong> (voce richiudibile, con il numero) compaiono, come informazione, le cartelle dei sistemi di versione («Repository di un sistema di versione») e il cestino del vault («Cestino del vault»). Non richiedono azioni e non sono contate tra i file non inviati.</p><p><strong>Riprova</strong> compare accanto ai file che l&#39;app ha smesso di ritentare e che possono essere reinviati (troppo grandi, cifratura non riuscita, spostamento che svuoterebbe una cartella condivisa, rifiutati dal server): rimette in coda quel file. <strong>Riprova tutti</strong> rimette in coda tutti questi file insieme. I pulsanti non ci sono per gli altri motivi, perché il file si sblocca in un altro modo (conflitti, rinomina) o da solo. Il file viene reinviato al ciclo successivo e, se il problema persiste, torna nell&#39;elenco.</p><p><strong>Che cosa non è elencato.</strong> Non si sincronizzano mai, e non compaiono nel blocco: i file di sistema come <code>.DS_Store</code> e <code>Thumbs.db</code>, i file temporanei e i dati locali del dispositivo in <code>.clarae</code>.</p><p><strong>Cartelle dei sistemi di versione.</strong> Le cartelle <code>.git</code>, <code>.hg</code>, <code>.svn</code>, <code>.bzr</code> e <code>.jj</code> (anche come file, a qualunque profondità, senza distinzione di maiuscole) non si sincronizzano mai, nemmeno se il vault è un repository: per portare il repository su un altro dispositivo usate il sistema di versione stesso. Le note del vault continuano a sincronizzarsi. Se copie di quei file sono già nel cloud (inviate da una versione precedente) <strong>restano lì e contano nella quota</strong>; i dispositivi aggiornati non le toccano né le cancellano.</p><h2 id="conflitti" tabindex="-1">Conflitti <a class="header-anchor" href="#conflitti" aria-label="Permalink to &quot;Conflitti&quot;">​</a></h2><p>Il merge avviene <strong>sul vostro dispositivo</strong>. Per le note Markdown le modifiche concorrenti in punti diversi si <strong>uniscono automaticamente</strong> (merge a tre vie); se le stesse righe cambiano da due parti, o per file di altro tipo, si crea una <strong>copia di conflitto</strong> (<code>nome (conflitto &lt;dispositivo&gt; &lt;data ora&gt;).ext</code>) e nessuna versione viene persa: <em>Risolvi conflitti di sincronizzazione</em> mostra le due versioni affiancate (diff) e permette di tenere una, l&#39;altra o unirle a mano. Le versioni scartate restano nella cronologia (<a href="./cronologia-recupero.html">Cronologia e recupero</a>). Tra i file di altro tipo, i disegni si fondono per elemento quando i dispositivi sono dello stesso utente, e la <strong>libreria di forme</strong> dei disegni si fonde sempre forma per forma: se due dispositivi ne aggiungono di diverse restano entrambe.</p><h2 id="piu-dispositivi" tabindex="-1">Più dispositivi <a class="header-anchor" href="#piu-dispositivi" aria-label="Permalink to &quot;Più dispositivi&quot;">​</a></h2><p>Accedete con lo stesso account sull&#39;altro dispositivo e collegate lo stesso vault. Per un vault <strong>privato</strong> serve la passphrase (o la chiave di recupero) su ogni dispositivo. Un dispositivo smarrito si revoca da <em>Cloud</em> (o dalla Web UI, pagina <em>Dispositivi</em>). Se un dispositivo risulta revocato, la sincronizzazione si ferma e compare «Registra di nuovo questo dispositivo»: riattiva la stessa riga.</p><h2 id="sospeso-quota-offline" tabindex="-1">Sospeso, quota, offline <a class="header-anchor" href="#sospeso-quota-offline" aria-label="Permalink to &quot;Sospeso, quota, offline&quot;">​</a></h2><ul><li><strong>Quota esaurita:</strong> le modifiche locali restano al sicuro sul dispositivo; liberate spazio o chiedete all&#39;amministratore di aumentare la quota; la sincronizzazione riprende da sola.</li><li><strong>Account sospeso:</strong> la sincronizzazione si ferma, i dati locali restano intatti.</li><li><strong>Offline:</strong> l&#39;app funziona normalmente, le modifiche si inviano al ritorno della rete.</li></ul>',30)])])}const v=i(n,[["render",l]]);export{m as __pageData,v as default};
